#define WIEGAND_VERSION "1.0"

/* Capture buffer. Credentials up to 64 bits are expected; the extra room lets
 * us tell "exactly 64" apart from "longer than we thought". */
#define MAX_BITS 128

/* DWT->CYCCNT ticks per microsecond (the CPU runs at 64 MHz). */
#define WIEGAND_TICKS_PER_US 64

/* How often the capture is polled for end-of-frame. */
#define WIEGAND_POLL_MS 50

/* ---- capture state (wiegand_capture.c) ---------------------------------- */
extern const GpioPin* const pinD0;
extern const GpioPin* const pinD1;
extern volatile int bit_count;
extern volatile uint32_t overflow_bits; /* pulses seen after the buffer filled */
extern volatile uint32_t glitch_count; /* edges too short to be a pulse */
extern volatile bool data[MAX_BITS];
extern volatile uint32_t data_fall[MAX_BITS];
extern volatile uint32_t data_rise[MAX_BITS];
extern bool data_saved;

#define WIEGAND_KEY_NAME_SIZE    32
#define WIEGAND_APPS_DATA_FOLDER EXT_PATH("apps_data")
#define WIEGAND_SAVE_FOLDER      \
    WIEGAND_APPS_DATA_FOLDER "/" \
                             "wiegand_raw"
#define WIEGAND_SAVE_EXTENSION ".wgn"

/* The stock 125 kHz RFID app reads from here. Writing a .rfid file here makes
 * it appear in that app's saved list for its decoder and analysis views. */
#define WIEGAND_RFID_FOLDER    EXT_PATH("lfrfid")
#define WIEGAND_RFID_EXTENSION ".rfid"

#define TAG "WIEGAND_RAW"

typedef enum {
    WiegandMainMenuScene,
    WiegandInstructionsScene,
    WiegandReadScene,
    WiegandCableTestScene,
    WiegandScanScene,
    WiegandDataScene,
    WiegandSaveScene,
    WiegandLoadScene,
    WiegandSceneCount,
} WiegandScene;

typedef enum {
    WiegandSubmenuView,
    WiegandWidgetView,
    WiegandTextInputView,
} WiegandView;

typedef struct App {
    SceneManager* scene_manager;
    ViewDispatcher* view_dispatcher;
    Submenu* submenu;
    Widget* widget;
    TextInput* text_input;
    DialogsApp* dialogs;
    NotificationApp* notifications;
    FuriString* file_path;
    char file_name[WIEGAND_KEY_NAME_SIZE];
    FuriTimer* timer;
    volatile uint8_t levels; /* last idle levels shown: bit0 = D0, bit1 = D1 */
    uint8_t level_divider;
    char status[128]; /* last save, load or export result, shown on the data screen */
} App;

typedef enum {
    WiegandMainMenuInstructions,
    WiegandMainMenuRead,
    WiegandMainMenuCableTest,
    WiegandMainMenuScan,
    WiegandMainMenuLoad,
} WiegandMainMenuSceneIndex;

typedef enum {
    WiegandMainMenuUnknownEvent,
    WiegandMainMenuInstructionsEvent,
    WiegandMainMenuReadEvent,
    WiegandMainMenuCableTestEvent,
    WiegandMainMenuScanEvent,
    WiegandMainMenuLoadEvent,
} WiegandMainMenuEvent;

typedef enum {
    WiegandDataSceneSaveButtonEvent = 50,
    WiegandDataSceneSaveFileEvent,
    WiegandDataSceneExportRfidEvent,
} WiegandDataEvent;

/* Sent from the poll timer to whichever capture scene is on screen. */
typedef enum {
    WiegandCaptureFrameEvent = 100, /* a complete frame is in the buffer */
    WiegandCaptureLevelEvent, /* idle line levels changed */
    WiegandCableTestResetEvent,
} WiegandCaptureEvent;

/* Timing summary of the frame in the buffer, in microseconds. */
typedef struct {
    uint32_t pulse_min;
    uint32_t pulse_max;
    uint32_t pulse_avg;
    uint32_t period_min;
    uint32_t period_max;
    uint32_t period_avg;
    bool has_period; /* false for a single-bit frame */
} WiegandTiming;

/* ---- capture (wiegand_capture.c) ---------------------------------------- */
void wiegand_capture_park_pins(void);
void wiegand_capture_release_pins(void);
void wiegand_capture_start(void);
void wiegand_capture_stop(void);
bool wiegand_capture_poll(void);
bool wiegand_capture_has_frame(void);
uint8_t wiegand_capture_levels(void);
void wiegand_capture_timing(WiegandTiming* timing);

/* Start/stop capture plus the poll timer for a scene. */
void wiegand_scene_capture_start(App* app);
void wiegand_scene_capture_stop(App* app);
void wiegand_timer_callback(void* context);
void wiegand_levels_text(uint8_t levels, char* out, size_t size);

/* ---- scenes -------------------------------------------------------------- */
void wiegand_menu_callback(void* context, uint32_t index);
void wiegand_main_menu_scene_on_enter(void* context);
bool wiegand_main_menu_scene_on_event(void* context, SceneManagerEvent event);

void wiegand_instructions_scene_on_enter(void* context);

